+function campaignScreen(kind='campaign'){activeAction=kind;selected=null;const list=kind==='scenario'?[
+{name:'The Hundred Years’ War',meta:'France & England · 1337',tag:'Theatre of war',desc:'A dynastic claim becomes a century-long struggle for the French crown.'},{name:'The Norman Conquest',meta:'England · 1066',tag:'Turning point',desc:'Three claimants. One island. A new order awaits.'},{name:'The Fall of Constantinople',meta:'Aegean · 1453',tag:'Last stand',desc:'The old imperial city faces its final siege.'}]:campaigns;
