+<div class="panel-actions"><button class="action" data-confirm disabled>Continue</button><button class="action secondary" data-close>Return</button></div>`)}
+function selectedCampaign(){const list=activeAction==='scenario'?[{name:'The Hundred Years’ War',meta:'France & England · 1337'},{name:'The Norman Conquest',meta:'England · 1066'},{name:'The Fall of Constantinople',meta:'Aegean · 1453'}]:campaigns;return list[Number(selected)]}
+function campaignBrief(){const chosen=selectedCampaign();if(!chosen)return;openModal(`${header('Chronicle preview','A realm awaits',chosen.meta)}<div class="empty-state"><div class="empty-mark">♜</div><h3>${chosen.name}</h3><p>This campaign is a preview of the world and its historical starting point. The strategy campaign is not yet implemented.</p></div><div class="panel-actions"><button class="action" data-close>Return to the cabinet</button></div>`)}
+function settingsScreen(){let music=localStorage.getItem('ch-music')!=='false',ambience=localStorage.getItem('ch-ambience')!=='false';openModal(`${header('Royal audience','Settings','Make the chronicle your own.')}
+<div class="setting"><div><div class="setting-name">Music</div><div class="setting-help">Main theme and score</div></div><button class="toggle" role="switch" aria-label="Music" aria-checked="${music}" data-setting="music"></button></div>
+<div class="setting"><div><div class="setting-name">Atmosphere</div><div class="setting-help">Ambient soundscape</div></div><button class="toggle" role="switch" aria-label="Atmosphere" aria-checked="${ambience}" data-setting="ambience"></button></div>
+<div class="setting"><div><div class="setting-name">Map detail</div><div class="setting-help">Visual detail level</div></div><input class="range" type="range" min="1" max="3" value="${localStorage.getItem('ch-detail')||'2'}" aria-label="Map detail"></div>
+<div class="panel-actions"><button class="action" data-close>Done</button></div>`)}
+function showEmpty(type){const title=type==='continue'?'No chronicle to resume':'No saved games';const copy=type==='continue'?'Your story has not yet begun. Start a new campaign to make your mark on history.':'There are no saved campaigns on this device yet.';openModal(`${header(type==='continue'?'The royal archive':'Saved chronicles',title,'')}
+<div class="empty-state"><div class="empty-mark">${type==='continue'?'♜':'▤'}</div><h3>${type==='continue'?'An unwritten chapter':'The archive is empty'}</h3><p>${copy}</p></div><div class="panel-actions">${type==='continue'?'<button class="action" data-go="new">Begin a campaign</button>':''}<button class="action secondary" data-close>Return</button></div>`)}
+function route(action){if(action==='new')campaignScreen();else if(action==='scenarios')campaignScreen('scenario');else if(action==='settings')settingsScreen();else if(action==='continue'||action==='load')showEmpty(action)}
+document.addEventListener('click',e=>{const action=e.target.closest('[data-action]')?.dataset.action;if(action){route(action);return}if(e.target.closest('.close,[data-close]')){closeModal();return}const go=e.target.closest('[data-go]')?.dataset.go;if(go){route(go);return}const card=e.target.closest('[data-select]');if(card){selected=card.dataset.select;panel.querySelectorAll('.option-card').forEach(el=>el.classList.toggle('selected',el===card));panel.querySelector('[data-confirm]').disabled=false;return}if(e.target.closest('[data-confirm]')){campaignBrief();return}const toggle=e.target.closest('[data-setting]');if(toggle){const next=toggle.getAttribute('aria-checked')!=='true';toggle.setAttribute('aria-checked',String(next));localStorage.setItem(`ch-${toggle.dataset.setting}`,String(next));return}if(e.target===modal)closeModal()});
+document.addEventListener('input',e=>{if(e.target.matches('.range'))localStorage.setItem('ch-detail',e.target.value)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.classList.contains('open'))closeModal()});
+</script>
+</body>
